// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, TransposeOperation } from '@stdlib/types/blas';

/**
* Interface describing `dlaln2`.
*/
interface Routine {
	/**
	* Solves a system of the form `(ca*A - w*D) X = s*B` or `(ca*A^T - w*D) X = s*B` with possible scaling and perturbation of `A`, where `A` is an `NA` by `NA` real matrix (`NA` is 1 or 2), `ca` is a real scalar, `D` is an `NA` by `NA` real diagonal matrix, and `w` is a real or complex scalar.
	*
	* ## Notes
	*
	* -   If `w` is complex (`NW = 2`), `X` and `B` are `NA` by `2` matrices whose first column contains the real part and whose second column contains the imaginary part.
	* -   `s` is a scaling factor (`<= 1`) chosen so that `X` can be computed without overflow. `X` is further scaled if necessary to assure that `norm(ca*A - w*D) * norm(X)` is less than overflow.
	* -   The function writes the scaling factor `s` and the infinity-norm of `X` to the first and second elements of `out`, respectively.
	* -   The function returns `1` if `ca*A - w*D` had to be perturbed to make its smallest (or only) singular value greater than `smin` and `0` otherwise.
	*
	* @param order - storage layout
	* @param trans - specifies whether `A` should be transposed
	* @param NA - size of the matrix `A` (either `1` or `2`)
	* @param NW - `1` if `w` is real and `2` if `w` is complex
	* @param smin - desired lower bound on the singular values of `A`
	* @param ca - coefficient by which `A` is multiplied
	* @param A - input matrix
	* @param lda - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param d1 - first diagonal element of `D`
	* @param d2 - second diagonal element of `D` (not used if `NA = 1`)
	* @param B - right-hand side matrix
	* @param ldb - stride of the first dimension of `B` (a.k.a., leading dimension of the matrix `B`)
	* @param wr - real part of `w`
	* @param wi - imaginary part of `w` (not used if `NW = 1`)
	* @param X - output matrix
	* @param ldx - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
	* @param out - output array containing the scaling factor and the infinity-norm of `X`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
	* var B = new Float64Array( [ 1.0, 2.0 ] );
	* var X = new Float64Array( 2 );
	* var out = new Float64Array( 2 );
	*
	* var info = dlaln2( 'row-major', 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, out );
	* // returns 0
	*
	* var s = out[ 0 ];
	* // returns 1.0
	*
	* var xnorm = out[ 1 ];
	* // returns ~1.3913
	*/
	( order: Layout, trans: TransposeOperation, NA: number, NW: number, smin: number, ca: number, A: Float64Array, lda: number, d1: number, d2: number, B: Float64Array, ldb: number, wr: number, wi: number, X: Float64Array, ldx: number, out: Float64Array ): number;

	/**
	* Solves a system of the form `(ca*A - w*D) X = s*B` or `(ca*A^T - w*D) X = s*B` with possible scaling and perturbation of `A` using alternative indexing semantics, where `A` is an `NA` by `NA` real matrix (`NA` is 1 or 2), `ca` is a real scalar, `D` is an `NA` by `NA` real diagonal matrix, and `w` is a real or complex scalar.
	*
	* ## Notes
	*
	* -   If `w` is complex (`NW = 2`), `X` and `B` are `NA` by `2` matrices whose first column contains the real part and whose second column contains the imaginary part.
	* -   `s` is a scaling factor (`<= 1`) chosen so that `X` can be computed without overflow. `X` is further scaled if necessary to assure that `norm(ca*A - w*D) * norm(X)` is less than overflow.
	* -   The function writes the scaling factor `s` and the infinity-norm of `X` to the first and second elements of `out`, respectively.
	* -   The function returns `1` if `ca*A - w*D` had to be perturbed to make its smallest (or only) singular value greater than `smin` and `0` otherwise.
	*
	* @param trans - specifies whether `A` should be transposed
	* @param NA - size of the matrix `A` (either `1` or `2`)
	* @param NW - `1` if `w` is real and `2` if `w` is complex
	* @param smin - desired lower bound on the singular values of `A`
	* @param ca - coefficient by which `A` is multiplied
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param d1 - first diagonal element of `D`
	* @param d2 - second diagonal element of `D` (not used if `NA = 1`)
	* @param B - right-hand side matrix
	* @param strideB1 - stride of the first dimension of `B`
	* @param strideB2 - stride of the second dimension of `B`
	* @param offsetB - starting index for `B`
	* @param wr - real part of `w`
	* @param wi - imaginary part of `w` (not used if `NW = 1`)
	* @param X - output matrix
	* @param strideX1 - stride of the first dimension of `X`
	* @param strideX2 - stride of the second dimension of `X`
	* @param offsetX - starting index for `X`
	* @param out - output array containing the scaling factor and the infinity-norm of `X`
	* @param strideOut - stride length for `out`
	* @param offsetOut - starting index for `out`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
	* var B = new Float64Array( [ 1.0, 2.0 ] );
	* var X = new Float64Array( 2 );
	* var out = new Float64Array( 2 );
	*
	* var info = dlaln2.ndarray( 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 1, 2, 0, 1.0, 1.0, B, 1, 2, 0, 0.5, 0.0, X, 1, 2, 0, out, 1, 0 );
	* // returns 0
	*
	* var s = out[ 0 ];
	* // returns 1.0
	*
	* var xnorm = out[ 1 ];
	* // returns ~1.3913
	*/
	ndarray( trans: TransposeOperation, NA: number, NW: number, smin: number, ca: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, d1: number, d2: number, B: Float64Array, strideB1: number, strideB2: number, offsetB: number, wr: number, wi: number, X: Float64Array, strideX1: number, strideX2: number, offsetX: number, out: Float64Array, strideOut: number, offsetOut: number ): number;
}

/**
* Solves a system of the form `(ca*A - w*D) X = s*B` or `(ca*A^T - w*D) X = s*B` with possible scaling and perturbation of `A`, where `A` is an `NA` by `NA` real matrix (`NA` is 1 or 2), `ca` is a real scalar, `D` is an `NA` by `NA` real diagonal matrix, and `w` is a real or complex scalar.
*
* ## Notes
*
* -   If `w` is complex (`NW = 2`), `X` and `B` are `NA` by `2` matrices whose first column contains the real part and whose second column contains the imaginary part.
* -   `s` is a scaling factor (`<= 1`) chosen so that `X` can be computed without overflow. `X` is further scaled if necessary to assure that `norm(ca*A - w*D) * norm(X)` is less than overflow.
* -   The function writes the scaling factor `s` and the infinity-norm of `X` to the first and second elements of `out`, respectively.
* -   The function returns `1` if `ca*A - w*D` had to be perturbed to make its smallest (or only) singular value greater than `smin` and `0` otherwise.
*
* @param order - storage layout
* @param trans - specifies whether `A` should be transposed
* @param NA - size of the matrix `A` (either `1` or `2`)
* @param NW - `1` if `w` is real and `2` if `w` is complex
* @param smin - desired lower bound on the singular values of `A`
* @param ca - coefficient by which `A` is multiplied
* @param A - input matrix
* @param lda - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param d1 - first diagonal element of `D`
* @param d2 - second diagonal element of `D` (not used if `NA = 1`)
* @param B - right-hand side matrix
* @param ldb - stride of the first dimension of `B` (a.k.a., leading dimension of the matrix `B`)
* @param wr - real part of `w`
* @param wi - imaginary part of `w` (not used if `NW = 1`)
* @param X - output matrix
* @param ldx - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
* @param out - output array containing the scaling factor and the infinity-norm of `X`
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
* var B = new Float64Array( [ 1.0, 2.0 ] );
* var X = new Float64Array( 2 );
* var out = new Float64Array( 2 );
*
* var info = dlaln2( 'row-major', 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, out );
* // returns 0
*
* var s = out[ 0 ];
* // returns 1.0
*
* var xnorm = out[ 1 ];
* // returns ~1.3913
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
* var B = new Float64Array( [ 1.0, 2.0 ] );
* var X = new Float64Array( 2 );
* var out = new Float64Array( 2 );
*
* var info = dlaln2.ndarray( 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 1, 2, 0, 1.0, 1.0, B, 1, 2, 0, 0.5, 0.0, X, 1, 2, 0, out, 1, 0 );
* // returns 0
*
* var s = out[ 0 ];
* // returns 1.0
*
* var xnorm = out[ 1 ];
* // returns ~1.3913
*/
declare var dlaln2: Routine;


// EXPORTS //

export = dlaln2;
